import networkx as nx

edges = [(1,16), (5,15), (4,13), (2,7), (6,13), (8,9), (2,6), (8,15), (5,6), (7,15), (2,5), (3,12), (1,11), (9,14), (4,7), (12,16), (4,16), (1,9), (7,11), (6,11), (13,14), (3,16), (10,12), (12,13), (0,12), (1,3), (0,14)]

G = nx.Graph()
G.add_nodes_from(range(17))
G.add_edges_from(edges)

# Check for self-loops and multiple edges
has_self_loops = len(list(nx.selfloop_edges(G))) > 0
has_multiple_edges = not nx.is_simple(G) if hasattr(nx, 'is_simple') else False # Wait, I already know it's simple.
# Let's just check manually.
is_simple = True
if len(list(nx.selfloop_edges(G))) > 0:
    is_simple = False
# Check for multiple edges
if len(edges) != len(set(tuple(sorted(e)) for e in edges)):
    is_simple = False

print(f"Is simple: {is_simple}")

# Check girth
# NetworkX doesn't have a direct girth function in all versions.
# Let's compute it.
def get_girth(G):
    if not nx.cycle_basis(G):
        return float('inf')
    return min(len(cycle) for cycle in nx.cycle_basis(G))

# Wait, cycle_basis doesn't necessarily give the shortest cycle.
# For girth, we need the shortest cycle.
# Let's use a BFS from each node to find the shortest cycle.
def find_girth(G):
    girth = float('inf')
    for node in G.nodes():
        # BFS to find the shortest cycle containing 'node'
        dist = {node: 0}
        parent = {node: None}
        queue = [node]
        while queue:
            u = queue.pop(0)
            for v in G.neighbors(u):
                if v not in dist:
                    dist[v] = dist[u] + 1
                    parent[v] = u
                    queue.append(v)
                elif v != parent[u]:
                    # Cycle found
                    girth = min(girth, dist[u] + dist[v] + 1)
    return girth

girth = find_girth(G)
print(f"Girth: {girth}")
